use super::*;
use crate::pet_data::{tests::Temp,startup::tests::Harness,current_profile,bootstrap,restore_cli};
use std::{fs,os::unix::fs::{DirBuilderExt,PermissionsExt,MetadataExt,symlink}};
struct Fixture{_source:Temp,target:Temp,owner:Harness,workspace:PathBuf,id:String,original:Vec<(Area,PathBuf,Vec<u8>)>}
impl Fixture{
 fn new()->Self{
  let source=Temp::new();let source_owner=Harness::new();let layout=source.basic();let active=Publication::begin(source_owner.claim(&layout).unwrap(),layout).ok().unwrap().publish().ok().unwrap();let paths=active.paths().unwrap();
  let extra=[(Area::Config,PathBuf::from("pet-runtime-consent-v1/.key.json"),b"synthetic application key only".as_slice()),(Area::Config,PathBuf::from("pet-runtime-consent-v1/old-grant.json"),b"synthetic signed historical grant bytes: never execute"),(Area::Config,PathBuf::from("pet-runtime-consent-v1.owners-v1/original.lock"),b""),(Area::Config,PathBuf::from("pet-runtime-results-v1/unknown.json"),b"unknown physical effect: do not replay"),(Area::Data,PathBuf::from("assistant/session-drafts.json"),b"{\"schemaVersion\":3,\"original\":true}"),(Area::Data,PathBuf::from("assistant/draft-source-fixture.json"),b"exact retained source UTF16 arrays [55296,0,57343]"),(Area::Data,PathBuf::from("assistant/memories.json"),b"selected scoped memory and revisions"),(Area::Data,PathBuf::from("assistant/attachments/one/original.txt"),b"attachment one"),(Area::Data,PathBuf::from("assistant/attachments/two/original.txt"),b"attachment two"),(Area::Config,PathBuf::from("future-module/state"),b"unknown future data, do not activate")];
  for(area,path,bytes)in extra{source.file(&match area{Area::Config=>paths.config.join(path),Area::Data=>paths.data.join(path)},bytes);}
  fs::write(paths.config.join("settings.json"),br#"{"autostart":true,"voice":true,"provider":"chosen-exact","model":"chosen-exact"}"#).unwrap();
  let mut original=vec![];for(area,root)in[(Area::Config,&paths.config),(Area::Data,&paths.data)]{for(path,bytes)in files(root){original.push((area,path,bytes));}}
  let workspace=source.0.join("backups");fs::DirBuilder::new().mode(0o700).create(&workspace).unwrap();let review=current_profile::Review::capture(active,&workspace).unwrap();let hash=review.fingerprint().unwrap();let(id,_)=review.copy(&hash).unwrap();
  let target=Temp::new();let layout=target.layout();for path in [&layout.legacy_config,&layout.legacy_data]{fs::DirBuilder::new().recursive(true).mode(0o700).create(path).unwrap();}let owner=Harness::new();Self{_source:source,target,owner,workspace,id,original}
 }
 fn layout(&self)->Layout{self.target.layout()}
 fn review(&self,mode:Mode)->Review{let layout=self.layout();Review::capture(self.owner.claim(&layout).unwrap(),layout,&self.workspace,&self.id,mode).unwrap()}
 fn archive(&self)->PathBuf{self.workspace.join(format!("current-profile-{}",self.id))}
 fn preserved(&self){for(area,path,bytes)in &self.original{assert_eq!(fs::read(self.archive().join(match area{Area::Config=>"config",Area::Data=>"data"}).join(path)).unwrap(),*bytes);}}
 fn restored(&self){let layout=self.layout();for(area,path,bytes)in &self.original{assert_eq!(fs::read(match area{Area::Config=>layout.config(),Area::Data=>layout.data()}.join(PAYLOAD).join(path)).unwrap(),*bytes);}assert!(!layout.config().join(ADMITTED).exists());}
}
fn files(root:&Path)->Vec<(PathBuf,Vec<u8>)>{fn walk(base:&Path,path:&Path,out:&mut Vec<(PathBuf,Vec<u8>)>){for entry in fs::read_dir(path).unwrap(){let path=entry.unwrap().path();if path.is_dir(){walk(base,&path,out);}else{out.push((path.strip_prefix(base).unwrap().to_path_buf(),fs::read(path).unwrap()));}}}let mut out=vec![];walk(root,root,&mut out);out.sort_by(|a,b|a.0.cmp(&b.0));out}
fn interrupt(f:&Fixture,at:Step)->String{let review=f.review(Mode::Fresh);let hash=review.fingerprint().unwrap();review.apply_using(&hash,|step|if step==at{Err(Error::Unavailable)}else{Ok(())}).err().unwrap().pair.unwrap()}
#[test]fn fresh_review_is_read_only_then_data_pair_and_portable_origin_are_restored_but_not_admitted(){
 let f=Fixture::new();let review=f.review(Mode::Fresh);let preview=review.preview().unwrap();assert_eq!(preview["result"],"dataRestoredInactive");assert_eq!(preview["executionAuthorityGranted"],false);assert_eq!(preview["runtimeActivationAvailable"],false);assert!(!preview.to_string().contains("synthetic application key"));let layout=f.layout();assert!(!layout.config().exists()&&!layout.data().exists());let hash=review.fingerprint().unwrap();let result=review.apply(&hash).unwrap();assert_eq!(result["status"],"dataRestoredInactive");f.restored();f.preserved();
 let a:Header=parse(&fs::read(layout.config().join(HEADER)).unwrap()).unwrap();let b:Header=parse(&fs::read(layout.data().join(HEADER)).unwrap()).unwrap();assert_eq!(a.version,2);assert_eq!(b.version,2);assert_eq!(a.pair,b.pair);assert_eq!(a.pair,result["pair"]);assert_eq!(fs::metadata(layout.config().join(ORIGIN)).unwrap().permissions().mode()&0o777,0o600);
 let origin:BackupOrigin=parse(&fs::read(layout.config().join(ORIGIN)).unwrap()).unwrap();assert!(origin.bounded());let before=[files(layout.config()),files(layout.data())];assert!(Active::open(f.owner.claim(&layout).unwrap(),layout.clone()).is_err());assert!(bootstrap::Session::prepare(f.owner.claim(&layout).unwrap(),layout.clone()).is_err());assert_eq!([files(layout.config()),files(layout.data())],before);
}
#[test]fn wrong_hash_changed_archive_replaced_parent_or_lost_owner_refuses_before_profile_roots(){
 for action in ["hash","archive","parent","owner"]{let f=Fixture::new();let review=f.review(Mode::Fresh);let mut hash=review.fingerprint().unwrap();let layout=f.layout();match action{"hash"=>hash="0".repeat(64),"archive"=>fs::write(f.archive().join("data/assistant/session-drafts.json"),b"changed").unwrap(),"parent"=>{fs::rename(&layout.legacy_config,f.target.0.join("original-config" )).unwrap();fs::DirBuilder::new().mode(0o700).create(&layout.legacy_config).unwrap();},"owner"=>f.owner.release(),_=>unreachable!()};assert!(review.apply(&hash).is_err());assert!(!layout.config().exists()&&!layout.data().exists());}
}
#[test]fn each_publication_boundary_recovers_under_fresh_review_and_same_pair_without_execution(){
 for point in [Step::ConfigCreated,Step::DataCreated,Step::BeforeCopy(0),Step::Copied,Step::ConfigComplete,Step::DataComplete,Step::Restored]{let f=Fixture::new();let pair=interrupt(&f,point);let review=f.review(Mode::Resume);let preview=review.preview().unwrap();assert_eq!(preview["pair"],pair);let hash=review.fingerprint().unwrap();let done=review.apply(&hash).unwrap();assert_eq!(done["pair"],pair);assert_eq!(done["runtimeActivationAvailable"],false);f.restored();f.preserved();}
}
#[test]fn verified_partial_prefix_is_appended_without_truncating_or_replacing_its_inode(){
 let f=Fixture::new();interrupt(&f,Step::DataCreated);let path=f.layout().config().join(PAYLOAD).join("settings.json");let full=f.original.iter().find(|(area,p,_)|*area==Area::Config&&p==Path::new("settings.json")).unwrap().2.clone();f.target.file(&path,&full[..8]);let inode=fs::metadata(&path).unwrap().ino();let review=f.review(Mode::Resume);let hash=review.fingerprint().unwrap();review.apply(&hash).unwrap();assert_eq!(fs::metadata(path).unwrap().ino(),inode);f.restored();f.preserved();
}
#[test]fn any_divergent_or_unknown_existing_subset_is_preserved_and_refused_before_new_bytes(){
 for action in ["prefix","extra"]{let f=Fixture::new();interrupt(&f,Step::DataCreated);let path=f.layout().config().join(PAYLOAD).join(if action=="prefix"{"settings.json"}else{"unknown-unreviewed-file"});f.target.file(&path,b"not original prefix");let before=[files(f.layout().config()),files(f.layout().data())];let review=f.review(Mode::Resume);let hash=review.fingerprint().unwrap();assert_eq!(review.apply(&hash).err().unwrap().error,Error::SourceChanged);assert_eq!([files(f.layout().config()),files(f.layout().data())],before);f.preserved();}
}
#[test]fn after_any_completion_missing_or_changed_payload_is_not_reconstructed(){
 for action in ["missing","changed","missingRoot"]{let f=Fixture::new();interrupt(&f,Step::ConfigComplete);let layout=f.layout();let path=layout.data().join(PAYLOAD).join("assistant/session-drafts.json");if action=="missingRoot"{fs::remove_dir_all(layout.data()).unwrap();}else if action=="missing"{fs::remove_file(&path).unwrap();}else{fs::write(&path,b"do not repair").unwrap();}let before=files(layout.config());let review=f.review(Mode::Resume);let hash=review.fingerprint().unwrap();assert!(review.apply(&hash).is_err());assert_eq!(files(layout.config()),before);if action=="missingRoot"{assert!(!layout.data().exists());}else if action=="missing"{assert!(!path.exists());}else{assert_eq!(fs::read(path).unwrap(),b"do not repair");}f.preserved();}
}
#[test]fn lost_ack_returns_same_receipt_with_no_file_changes_and_fresh_mode_never_overwrites(){
 let f=Fixture::new();let pair=interrupt(&f,Step::Restored);let before=[files(f.layout().config()),files(f.layout().data())];let review=f.review(Mode::Resume);let hash=review.fingerprint().unwrap();let first=review.apply(&hash).unwrap();assert_eq!(first["pair"],pair);let review=f.review(Mode::Resume);let hash=review.fingerprint().unwrap();assert_eq!(review.apply(&hash).unwrap(),first);assert_eq!([files(f.layout().config()),files(f.layout().data())],before);let layout=f.layout();assert!(matches!(Review::capture(f.owner.claim(&layout).unwrap(),layout,&f.workspace,&f.id,Mode::Fresh),Err(Error::TargetExists)));
}
#[test]fn altered_target_after_review_cannot_be_used_by_the_previously_approved_hash(){
 let f=Fixture::new();interrupt(&f,Step::DataCreated);let review=f.review(Mode::Resume);let hash=review.fingerprint().unwrap();let path=f.layout().data().join(PAYLOAD).join("unexpected");f.target.file(&path,b"changed after review");let before=[files(f.layout().config()),files(f.layout().data())];assert!(review.apply(&hash).is_err());assert_eq!([files(f.layout().config()),files(f.layout().data())],before);
}
#[test]fn active_legacy_unknown_parents_or_symlink_targets_are_not_adopted_as_restoration(){
 for action in ["legacy","symlink","unknown"]{let f=Fixture::new();let layout=f.layout();match action{"legacy"=>f.target.file(&layout.legacy_config.join("settings.json"),b"keep operational preferences"),"symlink"=>symlink(f.archive().join("config"),layout.config()).unwrap(),_=>f.target.file(&layout.legacy_config.join("foreign-file"),b"do not touch")};let before=fs::read(f.archive().join("config/settings.json")).unwrap();assert!(Review::capture(f.owner.claim(&layout).unwrap(),layout,&f.workspace,&f.id,Mode::Fresh).is_err());assert_eq!(fs::read(f.archive().join("config/settings.json")).unwrap(),before);}
}
#[test]fn malformed_source_intent_or_cross_pair_headers_are_never_repaired(){
 for action in ["intent","pair","origin"]{let f=Fixture::new();interrupt(&f,Step::DataCreated);let layout=f.layout();let path=layout.config().join(if action=="intent"{INTENT}else if action=="origin"{ORIGIN}else{HEADER});let mut value:serde_json::Value=serde_json::from_slice(&fs::read(&path).unwrap()).unwrap();if action=="intent"{value["archiveFence"]=serde_json::json!("0".repeat(64));}else if action=="pair"{value["pair"]=serde_json::json!("0".repeat(32));}else{value["schemaVersion"]=serde_json::json!(2);}fs::write(&path,serde_json::to_vec(&value).unwrap()).unwrap();let before=fs::read(&path).unwrap();assert!(Review::capture(f.owner.claim(&layout).unwrap(),layout,&f.workspace,&f.id,Mode::Resume).is_err());assert_eq!(fs::read(path).unwrap(),before);}
}
#[test]fn claim_loss_during_copy_stops_before_an_inactive_completion_receipt(){
 let f=Fixture::new();let review=f.review(Mode::Fresh);let hash=review.fingerprint().unwrap();assert!(review.apply_using(&hash,|step|{if step==Step::BeforeCopy(0){f.owner.release();}Ok(())}).is_err());assert!(!f.layout().config().join(RESTORED).exists());assert!(!f.layout().config().join(ADMITTED).exists());f.preserved();
}
#[test]fn restore_cli_review_and_approved_copy_share_native_owner_without_starting_application_state(){
 let f=Fixture::new();f.owner.release();let args=|hash:Option<&str>|{let mut v=vec!["coucou".to_string(),"--pets-profile-restore".into(),f.workspace.to_string_lossy().into_owned(),f.id.clone()];if let Some(h)=hash{v.extend(["--approve".into(),h.into()]);}restore_cli::parse(&v).unwrap().unwrap()};let preview=restore_cli::execute(args(None),f.owner.address(),"fr.louisraille.coucou",f.layout()).unwrap();assert!(!f.layout().config().exists());let copied=restore_cli::execute(args(preview["fingerprint"].as_str()),f.owner.address(),"fr.louisraille.coucou",f.layout()).unwrap();assert_eq!(copied["status"],"dataRestoredInactive");f.restored();f.preserved();
}
